import{_ as a,c as r,o as e,ag as l}from"./chunks/framework._xRlcm3f.js";const n=JSON.parse('{"title":"平台支持","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/index.md","filePath":"platforms/index.md","lastUpdated":1790228279000}'),d={name:"platforms/index.md"};function i(s,t,h,o,u,p){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="平台支持" tabindex="-1">平台支持 <a class="header-anchor" href="#平台支持" aria-label="Permalink to &quot;平台支持&quot;">​</a></h1><p>发布工具支持的平台已超过 30 个，按接入方式分为几类。每个平台都有一份独立的配置指南，说明需要填哪些字段、如何完成授权，以及常见问题怎么处理。</p><div class="tip custom-block"><p class="custom-block-title">不确定该看哪一篇？</p><p>对照下表选一个最接近的类型：静态博客（GitHub / GitLab 系）、博客协议（WordPress / MetaWeblog）、网页授权（Cookie 登录）或平台 API。</p></div><h2 id="通用平台" tabindex="-1">通用平台 <a class="header-anchor" href="#通用平台" aria-label="Permalink to &quot;通用平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>接入方式</th><th>说明</th></tr></thead><tbody><tr><td><a href="/siyuan-plugin-publisher/platforms/common-yuque.html">语雀（API）</a></td><td>API Token</td><td>需要语雀专业会员；支持知识空间与文档树</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/common-notion.html">Notion（API）</a></td><td>API Token</td><td>发布为 Notion 页面，支持分类与标签</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/common-halo.html">Halo（API）</a></td><td>API</td><td>适用于继续维护 Halo 2.9 站点</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/confluence.html">Confluence</a></td><td>API</td><td>发布为 Confluence 页面</td></tr></tbody></table><h2 id="github-系静态博客" tabindex="-1">GitHub 系静态博客 <a class="header-anchor" href="#github-系静态博客" aria-label="Permalink to &quot;GitHub 系静态博客&quot;">​</a></h2><p>文档提交到仓库，静态站点构建后生效。需要仓库写权限的 Token。</p><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><a href="/siyuan-plugin-publisher/platforms/common-github-hexo.html">Hexo</a></td><td>支持源码与构建产物两种模式</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-hugo.html">Hugo</a></td><td>标准 Hugo 目录结构</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-jekyll.html">Jekyll</a></td><td>支持 front-matter 与永久链接</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-vuepress.html">VuePress</a></td><td>VuePress 1.x 目录结构</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-vuepress2.html">VuePress 2</a></td><td>VuePress 2.x，支持 YAML 永久链接</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-vitepress.html">VitePress</a></td><td>VitePress 站点，支持 YAML 永久链接</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-quartz.html">Quartz</a></td><td>Quartz 数字花园</td></tr></tbody></table><h2 id="gitlab-系静态博客" tabindex="-1">GitLab 系静态博客 <a class="header-anchor" href="#gitlab-系静态博客" aria-label="Permalink to &quot;GitLab 系静态博客&quot;">​</a></h2><p>与 GitHub 系配置方式一致，指向自建或官方 GitLab 实例。</p><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabhexo.html">GitLab Hexo</a></td><td>Hexo 目录结构</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabhugo.html">GitLab Hugo</a></td><td>Hugo 目录结构</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabjekyll.html">GitLab Jekyll</a></td><td>Jekyll 目录结构</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabvuepress.html">GitLab VuePress</a></td><td>VuePress 1.x</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabvuepress2.html">GitLab VuePress 2</a></td><td>VuePress 2.x</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabvitepress.html">GitLab VitePress</a></td><td>VitePress</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/gitlab-gitlabastro.html">GitLab Astro</a></td><td>Astro 内容集合</td></tr></tbody></table><h2 id="网页授权平台" tabindex="-1">网页授权平台 <a class="header-anchor" href="#网页授权平台" aria-label="Permalink to &quot;网页授权平台&quot;">​</a></h2><p>用浏览器登录态（Cookie）发布，无需申请 API。配置页提供「去登录 → 自动读取 Cookie」流程。</p><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-wechat.html">微信公众号</a></td><td>发布到公众号草稿箱</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-juejin.html">掘金</a></td><td>默认分类「后端」、默认标签「程序员」</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-zhihu.html">知乎</a></td><td>需要选择专栏</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-jianshu.html">简书</a></td><td>需要选择文集</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-csdn.html">CSDN</a></td><td>支持专栏与标签</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-bilibili.html">哔哩哔哩</a></td><td>发布为专栏，需选择文集</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-yuqueweb.html">语雀网页版</a></td><td>Cookie 授权，不依赖会员</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/custom-haloweb.html">Halo 网页版</a></td><td>指向自建 Halo 站点</td></tr></tbody></table><h2 id="博客协议平台" tabindex="-1">博客协议平台 <a class="header-anchor" href="#博客协议平台" aria-label="Permalink to &quot;博客协议平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><a href="/siyuan-plugin-publisher/platforms/wordpress-wordpress.html">WordPress</a></td><td>自建 WordPress，XML-RPC</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/wordpress-wordpressdotcom.html">WordPress.com</a></td><td>官方托管站点</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/metaweblog-cnblogs.html">博客园</a></td><td>MetaWeblog 协议</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/metaweblog-typecho.html">Typecho</a></td><td>MetaWeblog 协议</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/metaweblog-jvue.html">Jvue</a></td><td>MetaWeblog 协议</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/metaweblog-metaweblog.html">MetaWeblog 通用</a></td><td>任何兼容 MetaWeblog 的站点</td></tr></tbody></table><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><a href="/siyuan-plugin-publisher/platforms/fs-local-system.html">本地系统</a></td><td>导出到本地目录，仅桌面端</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/telegraph.html">Telegraph</a></td><td>Telegraph 匿名发布</td></tr><tr><td><a href="/siyuan-plugin-publisher/platforms/github-astro.html">GitHub Astro</a></td><td>Astro 内容集合（GitHub）</td></tr></tbody></table><h2 id="平台能力对照" tabindex="-1">平台能力对照 <a class="header-anchor" href="#平台能力对照" aria-label="Permalink to &quot;平台能力对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>发布 / 更新 / 删除</td><td>所有平台均支持；删除仅清理插件侧的发布记录与平台文章</td></tr><tr><td>带图发布</td><td>取决于图床设置；平台原生直传或自备图床</td></tr><tr><td>分类 / 标签</td><td>需平台支持；未显式设置时部分平台会回退默认值</td></tr><tr><td>专栏 / 文集 / 知识空间</td><td>网页授权与语雀类平台需要选择</td></tr><tr><td>预览链接</td><td>由「预览规则」模板生成，用于「查看文章」</td></tr></tbody></table>',20)])])}const m=a(d,[["render",i]]);export{n as __pageData,m as default};
